def mapper(line):
    return [(word, 1) for word in line.lower().split()]

def shuffle(pairs):
    grouped = {}
    for key, value in pairs:
        grouped.setdefault(key, []).append(value)
    return grouped

def reducer(grouped):
    return {key: sum(values) for key, values in grouped.items()}

lines = [
    "data data pipeline",
    "pipeline runs data jobs",
]
mapped = []
for line in lines:
    mapped.extend(mapper(line))

grouped = shuffle(mapped)
result = reducer(grouped)
for word in sorted(result):
    print(f"{word}: {result[word]}")

replicas = 3
blocks = ["block_a", "block_b"]
placements = {b: [f"node_{i}" for i in range(replicas)] for b in blocks}
for block, nodes in placements.items():
    print(f"{block} replicado en {len(nodes)} nodos")
